1	package com.tainted.authuser.social;
2	
3	import com.tainted.authuser.error.InvalidTokenException;
4	
5	/**
6	 * provider 값으로 분기하는 소셜 검증기. provider별 mode(mock|real)에 따라
7	 * 실제 OAuth 검증기 또는 결정론적 mock 으로 위임한다(의도적 이기종 검증 경로).
8	 *
9	 * <ul>
10	 *   <li>google → OIDC ID-token JWKS 검증</li>
11	 *   <li>kakao  → Authorization code 교환 + user/me</li>
12	 *   <li>naver  → access token + nid/me 인트로스펙션</li>
13	 *   <li>toss   → 항상 mock (B2B 제휴 필요로 실연동 제외)</li>
14	 * </ul>
15	 */
16	public class CompositeSocialVerifier implements SocialVerifier {
17	
18	    private final SocialProperties props;
19	    private final SocialVerifier mock;
20	    private final SocialVerifier google;
21	    private final SocialVerifier kakao;
22	    private final SocialVerifier naver;
23	
24	    public CompositeSocialVerifier(SocialProperties props, SocialVerifier mock,
25	                                   SocialVerifier google, SocialVerifier kakao, SocialVerifier naver) {
26	        this.props = props;
27	        this.mock = mock;
28	        this.google = google;
29	        this.kakao = kakao;
30	        this.naver = naver;
31	    }
32	
33	    @Override
34	    public ExternalIdentity verify(String provider, String providerToken) {
35	        return switch (provider == null ? "" : provider) {
36	            case "google" -> pick("google", google).verify(provider, providerToken);
37	            case "kakao" -> pick("kakao", kakao).verify(provider, providerToken);
38	            case "naver" -> pick("naver", naver).verify(provider, providerToken);
39	            case "toss" -> mock.verify(provider, providerToken);
40	            default -> throw new InvalidTokenException("unsupported provider: " + provider);
41	        };
42	    }
43	
44	    private SocialVerifier pick(String provider, SocialVerifier real) {
45	        return "real".equalsIgnoreCase(props.modeOf(provider)) ? real : mock;
46	    }
47	}
48

