import com.tainted.authuser.error.InvalidTokenException;
import org.springframework.stereotype.Component;
import java.util.Set;

/**
 * 결정론적 소셜 검증 mock. 외부 호출 없음.
 * 유효 토큰 형식: "valid-<provider>-<seed>"  →  externalId = "<provider>:<seed>".
