{
  "endpoint": {
    "method": "POST",
    "path": "/api/v1/auth/login",
    "controller": "AuthController",
    "controllerFile": "src/main/java/com/tainted/authuser/web/AuthController.java",
    "handler": "login"
  },
  "className": "AuthLoginExistingUserBlackBoxTest",
  "sqlSlug": "auth-login-existing-user",
  "docLines": [
    "Covers AuthService.login's repository.findBySocialProviderAndExternalId hit path:",
    "pre-inserts a user_account row so login() must reuse it instead of creating a new one.",
    "Kept in a separate class because template-render fixtures are shared by every test in a class;",
    "the no-pre-existing-row (new user) scenarios live in AuthLoginBlackBoxTest instead."
  ],
  "auth": { "pattern": "none" },
  "seedParams": [
    { "name": "SEED", "kind": "id", "prefix": "" }
  ],
  "fixtures": {
    "setup": [
      { "table": "user_account",
        "values": {
          "id": { "refStr": "SEED" },
          "social_provider": "naver",
          "external_id": { "expr": "CONCAT('naver:', '${SEED}')" },
          "created_at": { "expr": "NOW()" }
        }
      }
    ],
    "teardown": [
      { "table": "user_account", "where": { "id": { "refStr": "SEED" } } }
    ],
    "preDelete": true
  },
  "tests": [
    {
      "name": "NTC_login_existingUser_naver",
      "comment": "existing row for this provider/externalId -> orElseGet is skipped, row is reused (no duplicate)",
      "jsonBody": { "provider": "naver", "providerToken": "valid-naver-${SEED}" },
      "expectStatus": 200,
      "expectBody": [
        { "path": "displayName", "equalTo": "익명" },
        { "path": "accessToken", "notNullValue": true }
      ],
      "dbAssertions": [
        { "query": "SELECT COUNT(*) FROM user_account WHERE id = ? AND social_provider='naver' AND external_id = CONCAT('naver:', ?)",
          "args": ["${SEED}", "${SEED}"], "expectEquals": "1" }
      ]
    }
  ]
}

