package com.tainted.authuser.blackbox;

import static com.tainted.authuser.blackbox.support.BlackBoxSupport.BASE_URL;
import static com.tainted.authuser.blackbox.support.BlackBoxSupport.executeSqlTemplate;
import static com.tainted.authuser.blackbox.support.BlackBoxSupport.queryScalar;
import static com.tainted.authuser.blackbox.support.BlackBoxSupport.testId;
import static com.tainted.authuser.blackbox.support.BlackBoxSupport.testSeq;
import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;
import static org.hamcrest.Matchers.notNullValue;

import java.util.Map;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInfo;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

import io.restassured.http.ContentType;

/**
 * Black-Box API Integration Test (template-rendered v2)
 *
 * @target-controller AuthController (src/main/java/com/tainted/authuser/web/AuthController.java)
 * @target-api POST /api/v1/auth/login
 *
 * AuthService.login: socialVerifier.verify(provider, providerToken) -> find-or-create UserAccount -> tokenService.issue.
 * social.*.mode defaults to mock (application.yml) so CompositeSocialVerifier delegates to MockSocialVerifier for google/kakao/naver/toss -> no outbound HTTP, no WireMock stub needed for this endpoint.
 * MockSocialVerifier throws InvalidTokenException (401, GlobalExceptionHandler) for unsupported provider / malformed token / empty seed; @NotBlank on provider/providerToken yields 400 before the service is reached.
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class AuthLoginBlackBoxTest {

    private Map<String, String> seed(TestInfo info) {
        return Map.of(
                "SEED", "" + testId(info));
    }

    private void arrange(Map<String, String> p) {
        executeSqlTemplate("sql/auth-login-teardown.sql", p);
        executeSqlTemplate("sql/auth-login-setup.sql", p);
    }

    @Test
    void NTC_login_newUser_google(TestInfo info) {
        // new user via google (mock mode) -> 200 + user_account row created
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body("{\"provider\": \"google\", \"providerToken\": \"valid-google-" + p.get("SEED") + "\"}")
            .when()
                    .post("/api/v1/auth/login")
            .then()
                    .statusCode(200)
                    .body("displayName", equalTo("익명"))
                    .body("accessToken", notNullValue());
            org.junit.jupiter.api.Assertions.assertEquals("1", queryScalar("SELECT COUNT(*) FROM user_account WHERE social_provider='google' AND external_id = CONCAT('google:', ?)", p.get("SEED")));
        } finally {
            executeSqlTemplate("sql/auth-login-teardown.sql", p);
        }
    }

    @Test
    void NTC_login_newUser_kakao(TestInfo info) {
        // new user via kakao (mock mode) -> 200 + user_account row created
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body("{\"provider\": \"kakao\", \"providerToken\": \"valid-kakao-" + p.get("SEED") + "\"}")
            .when()
                    .post("/api/v1/auth/login")
            .then()
                    .statusCode(200)
                    .body("displayName", equalTo("익명"))
                    .body("accessToken", notNullValue());
            org.junit.jupiter.api.Assertions.assertEquals("1", queryScalar("SELECT COUNT(*) FROM user_account WHERE social_provider='kakao' AND external_id = CONCAT('kakao:', ?)", p.get("SEED")));
        } finally {
            executeSqlTemplate("sql/auth-login-teardown.sql", p);
        }
    }

    @Test
    void NTC_login_newUser_naver(TestInfo info) {
        // new user via naver (mock mode) -> 200 + user_account row created
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body("{\"provider\": \"naver\", \"providerToken\": \"valid-naver-" + p.get("SEED") + "\"}")
            .when()
                    .post("/api/v1/auth/login")
            .then()
                    .statusCode(200)
                    .body("displayName", equalTo("익명"))
                    .body("accessToken", notNullValue());
            org.junit.jupiter.api.Assertions.assertEquals("1", queryScalar("SELECT COUNT(*) FROM user_account WHERE social_provider='naver' AND external_id = CONCAT('naver:', ?)", p.get("SEED")));
        } finally {
            executeSqlTemplate("sql/auth-login-teardown.sql", p);
        }
    }

    @Test
    void VTC_provider_NULL(TestInfo info) {
        // provider omitted -> @NotBlank violation -> 400
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body("{\"providerToken\": \"valid-google-" + p.get("SEED") + "\"}")
            .when()
                    .post("/api/v1/auth/login")
            .then()
                    .statusCode(400);;
        } finally {
            executeSqlTemplate("sql/auth-login-teardown.sql", p);
        }
    }

    @Test
    void VTC_provider_EMPTY(TestInfo info) {
        // provider empty string -> @NotBlank violation -> 400
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body("{\"provider\": \"\", \"providerToken\": \"valid-google-" + p.get("SEED") + "\"}")
            .when()
                    .post("/api/v1/auth/login")
            .then()
                    .statusCode(400);;
        } finally {
            executeSqlTemplate("sql/auth-login-teardown.sql", p);
        }
    }

    @Test
    void VTC_provider_WHITE_SPACE(TestInfo info) {
        // provider whitespace-only -> @NotBlank treats as blank -> 400
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body("{\"provider\": \" \", \"providerToken\": \"valid-google-" + p.get("SEED") + "\"}")
            .when()
                    .post("/api/v1/auth/login")
            .then()
                    .statusCode(400);;
        } finally {
            executeSqlTemplate("sql/auth-login-teardown.sql", p);
        }
    }

    @Test
    void VTC_provider_SPECIAL_CHAR(TestInfo info) {
        // SQL-injection-shaped provider -> not blank, fails switch match -> 401 (safe, no 500)
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body("{\"provider\": \"'; DROP TABLE--\", \"providerToken\": \"x\"}")
            .when()
                    .post("/api/v1/auth/login")
            .then()
                    .statusCode(401)
                    .body("title", equalTo("Invalid token"))
                    .body("detail", equalTo("unsupported provider: '; DROP TABLE--"));
        } finally {
            executeSqlTemplate("sql/auth-login-teardown.sql", p);
        }
    }

    @Test
    void VTC_provider_LENGTH_EXCEEDED(TestInfo info) {
        // provider far exceeds social_provider VARCHAR(32) -> fails switch match -> 401 (safe, no 500/truncation error)
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body("{\"provider\": \"xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\", \"providerToken\": \"x\"}")
            .when()
                    .post("/api/v1/auth/login")
            .then()
                    .statusCode(401)
                    .body("title", equalTo("Invalid token"))
                    .body("detail", equalTo("unsupported provider: xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx"));
        } finally {
            executeSqlTemplate("sql/auth-login-teardown.sql", p);
        }
    }

    @Test
    void VTC_providerToken_NULL(TestInfo info) {
        // providerToken omitted -> @NotBlank violation -> 400
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body("{\"provider\": \"google\"}")
            .when()
                    .post("/api/v1/auth/login")
            .then()
                    .statusCode(400);;
        } finally {
            executeSqlTemplate("sql/auth-login-teardown.sql", p);
        }
    }

    @Test
    void VTC_providerToken_EMPTY(TestInfo info) {
        // providerToken empty string -> @NotBlank violation -> 400
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body("{\"provider\": \"google\", \"providerToken\": \"\"}")
            .when()
                    .post("/api/v1/auth/login")
            .then()
                    .statusCode(400);;
        } finally {
            executeSqlTemplate("sql/auth-login-teardown.sql", p);
        }
    }

    @Test
    void VTC_providerToken_WHITE_SPACE(TestInfo info) {
        // providerToken whitespace-only -> @NotBlank treats as blank -> 400
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body("{\"provider\": \"google\", \"providerToken\": \" \"}")
            .when()
                    .post("/api/v1/auth/login")
            .then()
                    .statusCode(400);;
        } finally {
            executeSqlTemplate("sql/auth-login-teardown.sql", p);
        }
    }

    @Test
    void VTC_providerToken_SPECIAL_CHAR(TestInfo info) {
        // SQL/XSS-meta seed suffix on a valid token -> persists safely via parameterized JPA insert -> 200
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body("{\"provider\": \"google\", \"providerToken\": \"valid-google-" + p.get("SEED") + "DROP--<script>1=1\"}")
            .when()
                    .post("/api/v1/auth/login")
            .then()
                    .statusCode(200)
                    .body("displayName", equalTo("익명"));
            org.junit.jupiter.api.Assertions.assertEquals("1", queryScalar("SELECT COUNT(*) FROM user_account WHERE social_provider='google' AND external_id = CONCAT('google:', ?, 'DROP--<script>1=1')", p.get("SEED")));
        } finally {
            executeSqlTemplate("sql/auth-login-teardown.sql", p);
        }
    }

    @Test
    void ATC_login_unsupportedProvider(TestInfo info) {
        // provider not in {google,kakao,naver,toss} -> InvalidTokenException -> 401
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body("{\"provider\": \"facebook\", \"providerToken\": \"whatever\"}")
            .when()
                    .post("/api/v1/auth/login")
            .then()
                    .statusCode(401)
                    .body("title", equalTo("Invalid token"))
                    .body("detail", equalTo("unsupported provider: facebook"));
        } finally {
            executeSqlTemplate("sql/auth-login-teardown.sql", p);
        }
    }

    @Test
    void ATC_login_malformedToken(TestInfo info) {
        // kakao token missing required 'valid-kakao-' prefix -> InvalidTokenException -> 401, no row persisted
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body("{\"provider\": \"kakao\", \"providerToken\": \"not-a-valid-token\"}")
            .when()
                    .post("/api/v1/auth/login")
            .then()
                    .statusCode(401)
                    .body("title", equalTo("Invalid token"))
                    .body("detail", equalTo("malformed token for provider: kakao"));
            org.junit.jupiter.api.Assertions.assertEquals("0", queryScalar("SELECT COUNT(*) FROM user_account WHERE social_provider='kakao' AND external_id = CONCAT('kakao:', ?)", p.get("SEED")));
        } finally {
            executeSqlTemplate("sql/auth-login-teardown.sql", p);
        }
    }

    @Test
    void ATC_login_emptySeed(TestInfo info) {
        // kakao token has valid prefix but empty seed -> InvalidTokenException -> 401
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body("{\"provider\": \"kakao\", \"providerToken\": \"valid-kakao-\"}")
            .when()
                    .post("/api/v1/auth/login")
            .then()
                    .statusCode(401)
                    .body("title", equalTo("Invalid token"))
                    .body("detail", equalTo("empty seed"));
        } finally {
            executeSqlTemplate("sql/auth-login-teardown.sql", p);
        }
    }
}

