import static org.hamcrest.Matchers.equalTo;
import static org.hamcrest.Matchers.notNullValue;

import java.util.Map;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInfo;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

import io.restassured.http.ContentType;

/**
 * Black-Box API Integration Test (template-rendered v2)
 *
 * @target-controller AuthController (src/main/java/com/tainted/authuser/web/AuthController.java)
 * @target-api POST /api/v1/auth/login
 *
 * Covers AuthService.login's repository.findBySocialProviderAndExternalId hit path:
 * pre-inserts a user_account row so login() must reuse it instead of creating a new one.
 * Kept in a separate class because template-render fixtures are shared by every test in a class;
 * the no-pre-existing-row (new user) scenarios live in AuthLoginBlackBoxTest instead.
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class AuthLoginExistingUserBlackBoxTest {

    private Map<String, String> seed(TestInfo info) {
        return Map.of(
                "SEED", "" + testId(info));
    }

    private void arrange(Map<String, String> p) {
        executeSqlTemplate("sql/auth-login-existing-user-teardown.sql", p);
        executeSqlTemplate("sql/auth-login-existing-user-setup.sql", p);
    }

    @Test
    void NTC_login_existingUser_naver(TestInfo info) {
        // existing row for this provider/externalId -> orElseGet is skipped, row is reused (no duplicate)
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body("{\"provider\": \"naver\", \"providerToken\": \"valid-naver-" + p.get("SEED") + "\"}")
            .when()
                    .post("/api/v1/auth/login")
            .then()
                    .statusCode(200)
                    .body("displayName", equalTo("익명"))
                    .body("accessToken", notNullValue());
            org.junit.jupiter.api.Assertions.assertEquals("1", queryScalar("SELECT COUNT(*) FROM user_account WHERE id = ? AND social_provider='naver' AND external_id = CONCAT('naver:', ?)", p.get("SEED"), p.get("SEED")));
        } finally {
            executeSqlTemplate("sql/auth-login-existing-user-teardown.sql", p);
        }
    }
}

